for i,m in enumerate(modules):
    nav=''.join(f'<a href="{route}"'+(' aria-current="page"' if j==i else '')+f'><span class="num">0{j+1}</span><span>{modules[j]["title"]}</span></a>' for j,route in enumerate(routes))
    figures=''.join(picture(*f) for f in m['figures'])
    videos=''.join(f'<h3>{escape(title)}</h3><p class="small">{escape(author)}</p><iframe class="video" src="https://www.youtube-nocookie.com/embed/{vid}" title="{escape(title)} — {escape(author)}" loading="lazy" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p>{desc}</p><p class="small"><a href="https://www.youtube.com/watch?v={vid}">Watch on YouTube</a> if playback is blocked. Use YouTube’s captions where available; the written lesson provides a complete learning path.</p>' for vid,title,author,desc in m['videos'])
    prev=f'<a href="{routes[i-1]}">← {modules[i-1]["title"]}</a>' if i else '<span>Module 1 of 5</span>'
    nxt=f'<a href="{routes[i+1]}">{modules[i+1]["title"]} →</a>' if i<4 else '<a href="index.html">Return to Module 1 →</a>'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(m['intro'])}"><title>{m['title']} | Information Security Foundations</title><link rel="icon" type="image/svg+xml" href="{favicon}"><link rel="stylesheet" href="assets/style.css"><script src="assets/course.js" defer></script></head><body data-module="{i+1}"><a class="skip" href="#main">Skip to lesson</a><header><a class="brand" href="index.html"><span class="mark" aria-hidden="true">⌑</span><span>Information Security<br>Foundations</span></a><span class="small">An open, self-paced course<br>Learn · experiment · reflect</span></header><div class="shell"><aside><div class="course-nav"><span class="eyebrow">Your learning path</span><nav aria-label="Course modules">{nav}</nav><p class="small">Five modules. No prerequisites.<br>Begin with curiosity and a browser.</p><div class="sections"><span class="eyebrow">In this module</span><nav aria-label="Lesson sections"><a href="#objectives">Learning objectives</a><a href="#lecture">Read the lesson</a><a href="#watch">Watch &amp; learn</a><a href="#lab">Guided lab</a><a href="#summary">Takeaways</a></nav></div></div></aside><main id="main"><div class="hero"><span class="eyebrow">Module 0{i+1} / 05</span><h1>{m['title']}</h1><p class="intro">{m['intro']}</p><div class="meta"><span class="tag">{m['time']}</span><span class="tag">{m['level']}</span></div><a class="jump" href="#lecture">Begin the lesson ↓</a></div>
<section id="objectives" class="objectives"><h2>By the end, you can…</h2><ul>{''.join('<li>'+o+'</li>' for o in m['objectives'])}</ul></section>
<section id="lecture"><span class="eyebrow">01 / Read</span><h2>{m['subtitle']}</h2>{m['lecture']}</section>
<section id="watch"><span class="eyebrow">02 / Watch</span><h2>Another way into the ideas</h2><p>Choose the written lesson or combine these visual explanations with the guided exercise. The videos cover selected concepts; use the short written explanations to fill the remaining objectives.</p>{videos}</section>
<section id="lab" class="lab"><span class="eyebrow">03 / Practise</span><h2>{m['labtitle']}</h2><p>{m['labintro']}</p><p class="small">Allow 20–30 minutes. Exercises reset when you reload or leave. They do not save progress or submit your entries.</p><ol class="steps">{''.join('<li>'+s+'</li>' for s in m['steps'])}</ol>{figures}<div class="workspace">{m['workspace']}</div><noscript><p>The interactive lab needs JavaScript. You can still follow the illustrated scenario and read the worked solution below.</p></noscript>{solution(m['solution'])}</section>
<section><span class="eyebrow">04 / Reflect</span><h2>Check your understanding</h2><p>{m['check'][0]}</p><details><summary>Compare your answer</summary><p>{m['check'][1]}</p></details></section>
<section id="summary" class="summary"><h2>What to take with you</h2><ul>{''.join('<li>'+s+'</li>' for s in m['summary'])}</ul>{'<p>You have completed the learning path. Apply it to one system you use: identify an asset, a plausible threat, a control, and a way to check it.</p>' if i==4 else ''}</section>
<section class="sources"><h2>Keep exploring</h2><ul>{''.join(f'<li><a href="{url}">{title}</a></li>' for title,url in m['sources'])}</ul><p class="small">Independent educational material. External videos and resources belong to their creators; inclusion does not imply endorsement. References checked 6 October 2026.</p></section><nav class="pager" aria-label="Previous and next module">{prev}{nxt}</nav><footer>Information Security Foundations · Module {i+1} of 5<br>Practise only in these simulations or systems you own or have explicit permission to test.</footer></main></div></body></html>'''
    (DIST/routes[i]).write_text(html,encoding='utf-8')
